                                         ref floatN r, ref floatN rHat0, ref floatN p, ref floatN v, ref floatN t,
                                         ref floatN pHat, ref floatN sHat,
                                         int maxIter, float tol)
            where TOp : struct, IfloatLinearOperator
            where TPre : struct, IfloatPreconditioner
